import{z as B,x as i,o as r,c as d,q as l,j as s,D as A,d as E,s as t,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"寄存器重命名","description":"","frontmatter":{"title":"寄存器重命名","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/register-renaming.md","filePath":"cs/register-renaming.md","lastUpdated":1791413859000}'),p={name:"cs/register-renaming.md"};function m(R,a,D,T,C,c){const o=i("Mermaid");return r(),d("div",null,[a[2]||(a[2]=l('<h1 id="寄存器重命名" tabindex="-1">寄存器重命名 <a class="header-anchor" href="#寄存器重命名" aria-label="Permalink to &quot;寄存器重命名&quot;">​</a></h1><div class="epigraph"><p>架构寄存器只有一份名字；把每次写入映射到新的物理槽，写后读仍按数据流，写后写与写后读假相关从窗口里消失。</p><footer>—— 据 Keller, A Survey of Register Renaming, 1975；Hennessy and Patterson, CA:AQA 整理</footer></div><p><a href="/cs/speculation-recovery">上一课</a>规定误预测要恢复映射表，但还没说映射表里到底记什么。<a href="/cs/tomasulo">Tomasulo</a> 用标签代替架构名做唤醒，已经是重命名的一种实现。本课不重讲 CDB。缺口是把<strong>架构寄存器 → 物理寄存器</strong>钉成乱序核的前端动作：每次目的寄存器分配新物理槽，源寄存器查当前映射。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>ISA 把 <code>add x1, …</code> 的目的写成 <code>x1</code>。窗口里若已有一条未提交的 <code>add</code> 也写 <code>x1</code>，后面独立的 <code>add x1, x2, x3</code> 会被 WAW/WAR 堵住，即使数据流并不依赖那条旧写。<a href="/cs/ooo-rob">ROB</a> 已经要求提交有序，但若物理上只有一份 <code>x1</code>，年轻写仍不能先完成。缺口不是再加检查点，而是<strong>每次写分配新名字</strong>。</p><p><span class="marginnote">RISC-V 的 32 个整数架构寄存器在乱序核里会对应上百个物理寄存器。x0 永不分配：它不是写。</span></p><p><span class="marginnote">直觉类比：架构寄存器名像「现任经理」这个头衔，物理寄存器像具体的人。每次任命都招一个新人接任头衔，旧人（旧物理槽）仍留着供还没走完流程的部门查阅——头衔冲突自然消失，因为头衔永远指向最新的人。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>前端维护映射表 RAT：架构寄存器号 → 当前物理号（或「值已在架构堆」）。译码一条有目的寄存器的指令：</p><ol><li>读源操作数的物理号（从 RAT）；</li><li>从自由列表取一个新物理寄存器作为目的；</li><li>把旧目的物理号记到 ROB 项，供提交时释放或误预测时恢复；</li><li>更新 RAT：该架构寄存器现在指向新物理号。</li></ol><p><span class="marginnote">数字实例：RISC-V 只有 32 个架构整数寄存器，乱序核常配 200 个以上物理槽。窗口里同时飞的百余条微指令各自占独占目的槽；自由列表一旦耗尽（物理槽 \\lt 架构槽 + 在途写数），前端就停顿等提交释放。</span></p>',11)),(r(),s(n,null,{default:A(()=>[t(o,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20SRC%5B%22%E6%BA%90%EF%BC%9A%E6%9F%A5%20RAT%20%E5%BE%97%E7%89%A9%E7%90%86%E5%8F%B7%22%5D%20--%3E%20ISS%5B%22%E5%B8%A6%E7%9D%80%E7%89%A9%E7%90%86%E5%8F%B7%E8%BF%9B%E5%85%A5%E7%AA%97%E5%8F%A3%22%5D%0A%20%20DST%5B%22%E7%9B%AE%E7%9A%84%EF%BC%9A%E8%87%AA%E7%94%B1%E5%88%97%E8%A1%A8%E5%88%86%E9%85%8D%E6%96%B0%E7%89%A9%E7%90%86%E5%8F%B7%22%5D%20--%3E%20RAT%5B%22%E5%86%99%20RAT%22%5D%0A%20%20DST%20--%3E%20ROB%5B%22ROB%20%E8%AE%B0%E4%B8%8B%E8%A2%AB%E8%A6%86%E7%9B%96%E7%9A%84%E6%97%A7%E7%89%A9%E7%90%86%E5%8F%B7%22%5D%0A"})]),fallback:A(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"误预测：把 RAT 恢复成该分支检查点，或从 ROB 从头重放映射。提交：把 ROB 记下的旧物理号放回自由列表——此刻没有指令再读它。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"RAW 仍在：源物理号指向尚未写完的生产者，发射队列等唤醒。WAR/WAW 不再表现为「必须等旧写提交」：它们写的是不同物理槽。这正是上一课检查点要保存的对象——RAT 是推测状态。",-1)),a[6]||(a[6]=e("p",null,"与 Tomasulo 对照：保留站标签 ≈ 物理寄存器号；CDB 广播标签 ≈ 物理号写回。现代核把结果存在物理寄存器堆，保留站只存标签与就绪位，避免复制大向量。",-1)),a[7]||(a[7]=e("p",null,[e("span",{class:"marginnote"},[E("常见误区：初学者以为重命名能消除所有等待。它只拆"),e("strong",null,"假相关"),E("（WAR/WAW——名字撞车）；真相关 RAW 是数据流本身的依赖，生产者没算完消费者就必须等，重命名不改变这一点。")])],-1)),(r(),s(n,null,{default:A(()=>[t(o,{id:"mermaid-66",class:"mermaid",graph:"flowchart%20TD%0A%20%20T0%5B%22RAT%20%E5%88%9D%E5%A7%8B%EF%BC%9Ax1%20%E2%86%92%20p1%22%5D%20--%3E%20I1%5B%22I1%20%E5%86%99%20x1%EF%BC%9A%E5%88%86%E6%96%B0%E6%A7%BD%20p5%EF%BC%8CRAT%20%E6%94%B9%20x1%20%E2%86%92%20p5%22%5D%0A%20%20I1%20--%3E%20I2%5B%22I2%20%E4%B9%9F%E5%86%99%20x1%EF%BC%9A%E5%86%8D%E5%88%86%E6%96%B0%E6%A7%BD%20p8%EF%BC%8CRAT%20%E6%94%B9%20x1%20%E2%86%92%20p8%22%5D%0A%20%20I2%20--%3E%20WAW%5B%22%E4%B8%A4%E6%AC%A1%E5%86%99%E8%90%BD%E5%9C%A8%E4%B8%8D%E5%90%8C%E6%A7%BD%EF%BC%9AWAW%20%E6%B6%88%E5%A4%B1%22%5D%0A%20%20I3%5B%22I3%20%E8%AF%BB%20x1%EF%BC%9A%E6%9F%A5%20RAT%20%E5%BE%97%20p8%EF%BC%8C%E8%AF%BB%E5%88%B0%E6%9C%80%E6%96%B0%E5%80%BC%22%5D%0A%20%20I3%20--%3E%20WAR%5B%22%E4%B8%8E%20I1%20%E4%BA%92%E4%B8%8D%E7%AD%89%E5%BE%85%EF%BC%9AWAR%20%E6%B6%88%E5%A4%B1%22%5D%0A%20%20I2%20--%3E%20RAW%5B%22%E7%9C%9F%E4%BE%9D%E8%B5%96%E7%9A%84%E8%AF%BB%E8%80%85%E7%AD%89%20p8%20%E5%86%99%E5%AE%8C%EF%BC%9ARAW%20%E4%BF%9D%E7%95%99%22%5D%0A"})]),fallback:A(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=l('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把自由列表的宽度、回滚栈的层数写完，那是下一课物理寄存器堆。也不处理条件码 / 标志寄存器：x86 的标志是另一组要重命名的架构状态。内存重命名（store forwarding）是 LSQ，不是寄存器 RAT。</p><p>后课默认：窗口内只有物理寄存器号；架构名只在顺序前端与提交端出现。物理槽用完则前端停顿。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>每次写分配新物理寄存器，消除 WAR/WAW。</li><li>RAT 是推测状态，误预测必须恢复。</li><li>槽从哪来、何时真正释放，是下一课自由列表。</li><li>出处：Keller 重命名综述；Tomasulo 1967；Hennessy and Patterson, <em>CA:AQA</em>。</li></ul>',5))])}const x=B(p,[["render",m]]);export{f as __pageData,x as default};
